def greedy(L,k=10):
    names=list(L); sel=[]; 
    for _ in range(k):
        bn=None;be=9
        for n in names:
            if n in sel: continue
            A=np.column_stack([L[s] for s in sel+[n]])
            c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
            e=np.mean((A@c-dv_dt)**2)/np.var(dv_dt)
            if e<be: be=e;bn=n
